import{_ as t,o as a,c as i,a6 as s}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"TikTools 4.2.1-rc.1","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.1","docId":"releases.4.2.1-rc.1","translationKey":"releases.4.2.1-rc.1","locale":"fr","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f2b9e975511584a1a6156af8326d7603d73be54f10c97d7e46ed385def4755f6","translationRevision":"18f9da1b5f2d0a35a655be553b13107558b2bb912ddfa05742aa8e5725d01b36","order":10},"headers":[],"relativePath":"fr/releases/4.2.1-rc.1.md","filePath":"fr/releases/4.2.1-rc.1.md","lastUpdated":1794611623000}'),r={name:"fr/releases/4.2.1-rc.1.md"};function n(o,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="tiktools-421-rc1" tabindex="-1">TikTools 4.2.1-rc.1 <a class="header-anchor" href="#tiktools-421-rc1" aria-label="Permalink to &quot;TikTools 4.2.1-rc.1 {#tiktools-421-rc1}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">Objectif, état et prérequis <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;Objectif, état et prérequis {#goal-status-and-prerequisites}&quot;">​</a></h2><p>Utilisez ce rapport historique de version candidate pour reproduire les problèmes de récupération Cloud, Teams et AppImage Linux étudiés pour RC1. Il décrit la base applicative <code>338495a9</code> et une base serveur distincte <code>6a69c99</code>. Ces notes n’établissent pas la disponibilité actuelle des téléchargements RC1. Vérifiez les <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">ressources de version publiées</a> avant de choisir un installateur.</p><p>La version candidate enregistrée utilisait des paquets Linux AppImage, DEB et portables compilés localement lorsque Actions était désactivé. Elle ne comprenait pas de nouvel installateur Windows compilé. Conservez une sauvegarde et une copie isolée du profil concerné pour les tests de migration. La collaboration et la récupération des sections Cloud restent expérimentales.</p><h2 id="changes-in-this-candidate" tabindex="-1">Changements de cette version candidate <a class="header-anchor" href="#changes-in-this-candidate" aria-label="Permalink to &quot;Changements de cette version candidate {#changes-in-this-candidate}&quot;">​</a></h2><ul><li>Settings conserve le compte/la session et les diagnostics ; Plugins possède son catalogue, sa recherche, Changes et les actions d’installation. Les modèles et profils restent dans Automations.</li><li>Le panneau Changes partagé distingue une comparaison échouée d’un résultat vide réussi. La section Plugins envoie ses propres sélections/paramètres tout en conservant les autres files et téléchargements en cache.</li><li>La migration tolère l’absence d’un répertoire implicite de plugins intégrés, maintient des contraintes strictes sur les chemins configurés explicitement et identifie les identifiants de paquets manquants pour réparation avec examen. Les modifications en attente et conflits sont conservés.</li><li>Teams distingue l’inscription de ce PC comme hôte de la sélection d’un hôte sur un autre PC. Les invitations par pseudonyme lient le destinataire sélectionné ; l’approbation de l’hôte reste nécessaire.</li><li>L’aide guidée facultative suit l’état de configuration. L’empaquetage Linux inclut les utilitaires WebKit, plugins GStreamer et le scanner pour les vérifications multimédias ultérieures.</li></ul><h2 id="reproduce-and-inspect-the-expected-result" tabindex="-1">Reproduire et examiner le résultat attendu <a class="header-anchor" href="#reproduce-and-inspect-the-expected-result" aria-label="Permalink to &quot;Reproduire et examiner le résultat attendu {#reproduce-and-inspect-the-expected-result}&quot;">​</a></h2><ol><li>Notez la version affichée et le système d’exploitation. Ouvrez Plugins → Changes et conservez l’erreur exacte et l’identifiant de requête si le chargement échoue.</li><li>Dans le profil copié, prévisualisez la migration et examinez les identifiants exacts des paquets manquants avant réparation. Prévisualisez à nouveau ensuite ; les modifications en attente et conflits doivent toujours être présents.</li><li>Dans Teams, inscrivez le PC actuel avant de tester sa commande Start. Sélectionner l’hôte d’un autre PC ne doit pas autoriser le démarrage de celui-ci.</li><li>Vérifiez le démarrage AppImage puis l’audio/vidéo séparément. Atteindre l’interface seul ne prouve pas une lecture multimédia réussie.</li></ol><p>La recherche de pseudonymes et les invitations liées au destinataire nécessitent le serveur <code>6a69c99</code> et la migration <code>20261113000001_remote_invitation_recipients.sql</code>. Installer cette version candidate ne déploie pas ce serveur.</p><h2 id="recovery-and-evidence-limits" tabindex="-1">Récupération et limites des preuves <a class="header-anchor" href="#recovery-and-evidence-limits" aria-label="Permalink to &quot;Récupération et limites des preuves {#recovery-and-evidence-limits}&quot;">​</a></h2><p>Si une comparaison échoue, conservez la raison native et réessayez via le panneau pris en charge. Ne supprimez pas l’état en attente et ne déduisez pas une migration réussie d’une vérification de compatibilité. Recueillez version, action et détails diagnostiques expurgés avec le <a href="./../user/preferences/troubleshooting.html">guide de dépannage</a>.</p><p>Le rapport original indique des vérifications de l’interface, du moteur de synchronisation, de l’isolation des destinataires et de deux hôtes natifs/relais à sa version de base. Ces vérifications datées ne constituent pas une nouvelle validation en production. Le détenteur historique du verrou SQLite n’a pas été identifié. À RC1, les adaptateurs Cloud Variables et Overlay étaient inachevés et Automations comparait une référence locale. Lisez les <a href="./4.2.1-rc.3.html">notes candidates ultérieures</a> et le <a href="./../user/cloud/changes.html">guide Changes actuel</a> pour le périmètre suivant.</p><p>Le <a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.1.md" target="_blank" rel="noreferrer">rapport de version original</a> est conservé comme preuve datée. Revenez à l’<a href="./">index des versions</a>.</p>',13)])])}const h=t(r,[["render",n]]);export{m as __pageData,h as default};
